harray='0 23 12.4 64.6'/%3E%3Cuse href='%23r' stroke-opacity='.07' stroke-dasharray='0 24.9 10.5 64.6'/%3E%3Cuse href='%23r' stroke-opacity='.08' stroke-dasharray='0 26.6 8.7 64.7'/%3E%3Cuse href='%23r' stroke-opacity='.08' stroke-dasharray='0 28.2 7 64.8'/%3E%3Cuse href='%23r' stroke-opacity='.09' stroke-dasharray='0 29.6 5.5 64.9'/%3E%3Cuse href='%23r' stroke-opacity='.09' stroke-dasharray='0 30.9 4.2 64.9'/%3E%3Cuse href='%23r' stroke-opacity='.1' stroke-dasharray='0 32 3.1 64.9'/%3E%3Cuse href='%23r' stroke-opacity='.1' stroke-dasharray='0 32.9 2.1 65'/%3E%3Cuse href='%23r' stroke-opacity='.11' stroke-dasharray='0 33.7 1.4 64.9'/%3E%3Cuse href='%23r' stroke-opacity='.11' stroke-dasharray='0 34.2 .8 65'/%3E%3Cuse href='%23r' stroke-opacity='.12' stroke-dasharray='0 34.4 .6 65'/%3E%3Canimate attributeName='stroke-dashoffset' values='0;-100' dur='9s' repeatCount='indefinite'/%3E%3C/g%3E%3C/svg%3E")}
.dark{--sx-r-card:0px;--sx-r-md:0px;--sx-r-btn:0px;--sx-card:0 0 0 2px rgb(249 253 255 / 0.22), 4px 4px 0 rgb(0 0 0 / .6);--sx-pop:0 0 0 2px rgb(249 253 255 / 0.22), 6px 6px 0 rgb(0 0 0 / .6);--sx-edge:none;--sx-btn:2px 2px 0 rgb(0 0 0 / .6);--sx-pill:0 0 0 2px rgb(249 253 255 / 0.22);--sx-accent:#69bfb5;--sx-accent-2:#6fbbd7;--sx-accent-ink:#69bfb5;--sx-accent-fill:#44b1a6;--sx-accent-fg:#031412;--sx-glow:transparent;--sx-rim-c:linear-gradient(to bottom right,#56bbe4,#47c4b7,#8abe78);--sx-ambient:5%;--sx-tint:#44b1a642;--sx-ring:#36a69b9e;--sx-line:rgb(249 253 255 / 0.145);--sx-line-3:rgb(249 253 255 / 0.22);--sx-fg:#def0fc;--sx-card-bg:#000b15;--sx-fg-2:#94a8b6;--sx-fg-3:#8c9fac;--sx-fg-4:#60737f;--sx-sunken:#00060d;--sx-raised:#001421;--sx-hover:rgb(249 253 255 / 0.059);--sx-seg:0 0 0 2px rgb(249 253 255 / 0.22);--sx-veil:rgb(0 0 0 / 0.36)}
:root:not(.dark){--sx-r-card:0px;--sx-r-md:0px;--sx-r-btn:0px;--sx-card:0 0 0 2px rgb(0 53 71 / 0.2), 4px 4px 0 #0d151933;--sx-pop:0 0 0 2px rgb(0 53 71 / 0.2), 6px 6px 0 #0d151933;--sx-edge:none;--sx-btn:2px 2px 0 #0d151933;--sx-pill:0 0 0 2px rgb(0 53 71 / 0.2);--sx-accent:#008077;--sx-accent-2:#0a647d;--sx-accent-ink:#01635c;--sx-accent-fill:#008077;--sx-accent-fg:#fbfffe;--sx-glow:transparent;--sx-rim-c:linear-gradient(to bottom right,#0b799e,#117f77,#477f33);--sx-ambient:3%;--sx-tint:#00807742;--sx-ring:#007b72b9;--sx-line:rgb(0 53 71 / 0.122);--sx-line-3:rgb(0 53 71 / 0.2);--sx-fg:#0d1519;--sx-card-bg:#ffffff;--sx-fg-2:#465b65;--sx-fg-3:#495b64;--sx-fg-4:#768d97;--sx-sunken:#e8f8ff;--sx-raised:#ffffff;--sx-hover:rgb(0 53 71 / 0.039);--sx-seg:0 0 0 2px rgb(0 53 71 / 0.2);--sx-veil:rgb(20 24 22 / 0.16)}
::selection{background:var(--sx-tint)}
[data-workspace-area="conversation"]{background-image:radial-gradient(120% 55% at 50% -12%,color-mix(in srgb,var(--sx-accent) var(--sx-ambient),transparent),transparent 62%)!important}
[data-slot="composer-host"]{border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-card)!important}
[data-slot="composer-shell"]::before{border-radius:var(--sx-r-card)!important}
[data-user-message-bubble]{border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-edge)!important}
.chat-markdown-codeblock{border-radius:var(--sx-r-md)!important;box-shadow:var(--sx-edge),0 0 0 1px var(--sx-line)!important}
[data-thread-details-card]{border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-card)!important}
:is([data-slot="dialog-popup"],[data-slot="alert-dialog-popup"],[data-slot="command-dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="select-popup"],[data-slot="combobox-popup"],[data-slot="autocomplete-popup"]){border-radius:var(--sx-r-card)!important;box-shadow:var(--sx-pop)!important}
[data-slot="tooltip-popup"]{border-radius:var(--sx-r-md)!important}
:root:root{--control-radius:var(--sx-r-btn)}
:is([data-slot="button"],[data-slot="select-trigger"]){border-radius:var(--sx-r-btn)!important}
[data-slot="input"]{border-radius:var(--sx-r-md)!important;transition:box-shadow var(--sx-med,220ms) ease}
[data-slot="input"]:focus-visible{box-shadow:0 0 0 3px color-mix(in srgb,var(--sx-accent) 22%,transparent)!important}
[data-sidebar-row]{border-radius:var(--sx-r-md)!important}
svg.lucide{stroke-width:1.75}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--sx-line-3);border-radius:999px;border:3px solid transparent;background-clip:content-box}
::-webkit-scrollbar-thumb:hover{background:var(--sx-tint);background-clip:content-box}
[data-slot="scroll-area-thumb"]{border-radius:999px!important}
/* ===== Somnus chrome ===== */
/* --- model picker: one column; providers as a strip, models, then effort as a segmented control --- */
div:has(>div>[data-model-picker-effort]){width:400px!important;max-width:calc(100vw - 24px)!important}
div:has(>[data-model-picker-effort]){flex-direction:column!important;height:auto!important;width:100%!important}
[data-model-picker-content]{width:380px!important;max-width:calc(100vw - 24px)!important;flex-direction:column!important;max-height:316px!important}
div:has(>[data-model-picker-effort])>[data-model-picker-content]{width:100%!important;max-width:none!important}
[data-model-picker-sidebar]{width:100%!important;height:46px!important;flex:none!important;background:transparent!important;border-bottom:1px solid var(--sx-line)!important}
[data-model-picker-sidebar]>div{overflow-x:auto!important;overflow-y:hidden!important}
[data-model-picker-sidebar] .min-h-full{flex-direction:row!important;min-height:0!important;height:100%!important;align-items:center!important;gap:3px!important;padding:6px 8px!important}
[data-model-picker-provider]{width:34px!important;flex:none!important}
[data-model-picker-provider]>*{border-radius:var(--sx-r-md)!important;transition:background-color var(--sx-fast) var(--sx-ease),box-shadow var(--sx-med) var(--sx-ease),scale var(--sx-sp-press-dur) var(--sx-sp-press)!important}
[data-model-picker-provider]>*:active{scale:.9}
[data-model-picker-provider] :is([aria-pressed="true"],[data-pressed],[aria-selected="true"]){background:color-mix(in srgb,var(--sx-accent) 16%,transparent)!important;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sx-accent) 30%,transparent),0 4px 14px -6px var(--sx-glow)!important}
[data-model-picker-provider="favorites"] :is([aria-pressed="true"],[data-pressed]) svg{color:var(--sx-accent)!important;fill:var(--sx-accent)!important}
[data-model-picker-selected-indicator]{display:none!important}
[data-model-picker-content]>:last-child{background:transparent!important;border-left:none!important}
[data-model-picker-content] input{font-size:13.5px!important}
[data-model-picker-content] :is([data-slot="combobox-item"],[role="option"]){position:relative;border-radius:var(--sx-r-md)!important;min-height:34px;transition:background-color var(--sx-fast) var(--sx-ease),color var(--sx-fast) var(--sx-ease),padding-left var(--sx-sp-glide-dur) var(--sx-sp-glide)!important}
[data-model-picker-content] :is([data-slot="combobox-item"],[role="option"])[data-highlighted]{background:var(--sx-hover)!important}
[data-model-picker-content] :is([data-slot="combobox-item"],[role="option"]):is([data-selected],[aria-selected="true"]){background:color-mix(in srgb,var(--sx-accent) 12%,transparent)!important;color:var(--sx-accent-ink)!important;padding-left:14px!important}
[data-model-picker-content] :is([data-slot="combobox-item"],[role="option"])::before{content:"";position:absolute;left:4px;top:28%;bottom:28%;width:3px;border-radius:3px;background:var(--sx-accent);box-shadow:0 0 10px var(--sx-accent);scale:1 0;opacity:0;transition:scale var(--sx-sp-pop-dur) var(--sx-sp-pop),opacity var(--sx-fast) var(--sx-ease)}
[data-model-picker-content] :is([data-slot="combobox-item"],[role="option"]):is([data-selected],[aria-selected="true"])::before{scale:1 1;opacity:1}
[data-model-picker-effort]{width:100%!important;height:auto!important;max-height:none!important;border-left:none!important;border-top:1px solid var(--sx-line)!important;background:transparent!important;padding:4px 10px 10px!important;overflow-x:hidden!important}
[data-model-picker-effort] [role="radiogroup"]:has(>[data-effort-level]){display:flex!important;flex-direction:row!important;flex-wrap:wrap!important;gap:2px!important;height:auto!important;padding:3px!important;border-radius:calc(var(--sx-r-md) + 3px)!important;background:var(--sx-sunken)!important;box-shadow:inset 0 0 0 1px var(--sx-line)!important}
[data-effort-level]{flex:1 1 auto!important;width:auto!important;min-width:max-content!important;height:28px!important;justify-content:center!important;padding:0 10px!important;border-radius:var(--sx-r-md)!important;font-size:12px!important;color:var(--sx-fg-2)!important;background:transparent!important;transition:background-color var(--sx-med) var(--sx-ease),color var(--sx-fast) var(--sx-ease),box-shadow var(--sx-med) var(--sx-ease),scale var(--sx-sp-press-dur) var(--sx-sp-press)!important}
[data-effort-level]:hover{color:var(--sx-fg)!important;background:var(--sx-hover)!important}
[data-effort-level]:active{scale:.94}
[data-effort-level]>:not(:first-child){display:none!important}
[data-effort-level][aria-checked="true"]{background:var(--sx-raised)!important;color:var(--sx-accent-ink)!important;font-weight:550!important;box-shadow:var(--sx-seg)!important}
[data-model-picker-effort] [data-effort-row]:not([data-effort-level]){border-radius:var(--sx-r-md)!important;font-size:13px!important;margin-top:6px}
[data-model-picker-effort] [data-effort-row]:not([data-effort-level])[aria-checked="true"]{color:var(--sx-accent-ink)!important;background:color-mix(in srgb,var(--sx-accent) 10%,transparent)!important}
/* FRAGILE: section labels in the effort column */
[data-model-picker-effort] .font-medium.text-muted-foreground.text-xs{text-transform:uppercase;letter-spacing:.07em;font-size:11px!important;padding-top:10px!important}
div:has(>[data-model-picker-effort])+*{border-top:1px solid var(--sx-line)}
/* --- composer: chips, the lit send button, the effort glyph in the accent --- */
[data-chat-provider-model-picker]{border-radius:999px!important;transition:background-color var(--sx-fast) var(--sx-ease),box-shadow var(--sx-med) var(--sx-ease),scale var(--sx-sp-press-dur) var(--sx-sp-press)!important}
[data-chat-provider-model-picker]:hover{background:var(--sx-hover)!important;box-shadow:inset 0 0 0 1px var(--sx-line)}
[data-chat-provider-model-picker]:is([data-popup-open],[aria-expanded="true"]){background:color-mix(in srgb,var(--sx-accent) 14%,transparent)!important;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sx-accent) 30%,transparent)!important;color:var(--sx-accent-ink)!important}
[data-chat-provider-model-picker-icon]{filter:drop-shadow(0 0 6px color-mix(in srgb,var(--sx-accent) 35%,transparent))}
[data-composer-effort-glyph] rect[opacity="1"]{fill:var(--sx-accent)}
[data-composer-permissions-trigger]{border-radius:999px!important}
[data-chat-composer-form] button[type="submit"]{border-radius:999px!important;background:var(--sx-accent-fill)!important;color:var(--sx-accent-fg)!important;border:none!important;box-shadow:0 0 0 1px color-mix(in srgb,var(--sx-accent) 40%,transparent),0 6px 18px -6px var(--sx-glow),inset 0 1px 0 rgb(255 255 255 / .22)!important;transition:scale var(--sx-sp-press-dur) var(--sx-sp-press),box-shadow var(--sx-med) var(--sx-ease),background-color var(--sx-med) var(--sx-ease),opacity var(--sx-med) var(--sx-ease)!important}
[data-chat-composer-form] button[type="submit"] svg{color:var(--sx-accent-fg)!important;stroke:var(--sx-accent-fg)!important}
[data-chat-composer-form] button[type="submit"]:hover:not(:disabled){scale:1.06;box-shadow:0 0 0 1px color-mix(in srgb,var(--sx-accent) 55%,transparent),0 8px 26px -6px var(--sx-glow),inset 0 1px 0 rgb(255 255 255 / .25)!important}
[data-chat-composer-form] button[type="submit"]:active:not(:disabled){scale:.9}
[data-chat-composer-form] button[type="submit"]:disabled{background:var(--sx-sunken)!important;box-shadow:inset 0 0 0 1px var(--sx-line)!important;opacity:1!important}
[data-chat-composer-form] button[type="submit"]:disabled svg{color:var(--sx-fg-4)!important;stroke:var(--sx-fg-4)!important}
/* --- the project picker in a new thread: an inline link in the heading, a chip under it --- */
[data-draft-project-trigger]{cursor:pointer;transition:color var(--sx-fast) var(--sx-ease),background-color var(--sx-fast) var(--sx-ease),text-decoration-color var(--sx-med) var(--sx-ease)}
h1 [data-draft-project-trigger]{color:var(--sx-accent-ink)!important;text-decoration:underline dotted 2px!important;text-decoration-color:color-mix(in srgb,var(--sx-accent) 45%,transparent)!important;text-underline-offset:.16em!important}
h1 [data-draft-project-trigger]:is(:hover,[data-popup-open]){text-decoration-style:solid!important;text-decoration-color:var(--sx-accent)!important}
p>[data-draft-project-trigger]{display:inline-flex!important;align-items:center!important;gap:6px;padding:3px 10px!important;border-radius:999px!important;font-size:13px!important;color:var(--sx-fg-2)!important;text-decoration:none!important;box-shadow:inset 0 0 0 1px var(--sx-line)}
p>[data-draft-project-trigger]:is(:hover,[data-popup-open]){background:var(--sx-hover)!important;color:var(--sx-fg)!important;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sx-accent) 35%,transparent)}
p>[data-draft-project-trigger]::before,p>[data-draft-project-trigger]::after{content:"";background:currentColor}
p>[data-draft-project-trigger]::before{flex:0 0 13px;width:13px;height:13px;-webkit-mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2'%20stroke-linejoin%3D'round'%3E%3Cpath%20d%3D'M20%2020a2%202%200%200%200%202-2V8a2%202%200%200%200-2-2h-7.9a2%202%200%200%201-1.69-.9L9.6%203.9A2%202%200%200%200%207.93%203H4a2%202%200%200%200-2%202v13a2%202%200%200%200%202%202Z'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2'%20stroke-linejoin%3D'round'%3E%3Cpath%20d%3D'M20%2020a2%202%200%200%200%202-2V8a2%202%200%200%200-2-2h-7.9a2%202%200%200%201-1.69-.9L9.6%203.9A2%202%200%200%200%207.93%203H4a2%202%200%200%200-2%202v13a2%202%200%200%200%202%202Z'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat}
p>[data-draft-project-trigger]::after{flex:0 0 10px;width:10px;height:10px;opacity:.7;-webkit-mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2.5'%20stroke-linecap%3D'round'%3E%3Cpath%20d%3D'm6%209%206%206%206-6'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;mask:url("data:image/svg+xml,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20viewBox%3D'0%200%2024%2024'%20fill%3D'none'%20stroke%3D'black'%20stroke-width%3D'2.5'%20stroke-linecap%3D'round'%3E%3Cpath%20d%3D'm6%209%206%206%206-6'%2F%3E%3C%2Fsvg%3E") center/contain no-repeat}
/* --- sidebar: a search pill, a lit New thread, quiet shelf labels, live timers --- */
/* FRAGILE: the header row holding search + actions */
div:has(>div.shrink-0>[aria-label^="New thread"])>div:not(.shrink-0){border-radius:999px!important;background:var(--sx-sunken)!important;box-shadow:inset 0 0 0 1px var(--sx-line)!important;transition:box-shadow var(--sx-med) var(--sx-ease),background-color var(--sx-med) var(--sx-ease)!important}
div:has(>div.shrink-0>[aria-label^="New thread"])>div:not(.shrink-0):focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sx-accent) 55%,transparent),0 0 0 3px color-mix(in srgb,var(--sx-accent) 16%,transparent)!important;--tw-ring-color:transparent!important}
[data-slot="sidebar"] [aria-label^="New thread"]{border-radius:999px!important;color:var(--sx-accent-ink)!important;transition:background-color var(--sx-fast) var(--sx-ease),box-shadow var(--sx-med) var(--sx-ease),scale var(--sx-sp-press-dur) var(--sx-sp-press)!important}
[data-slot="sidebar"] [aria-label^="New thread"]:hover{background:color-mix(in srgb,var(--sx-accent) 14%,transparent)!important;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sx-accent) 30%,transparent),0 4px 16px -6px var(--sx-glow)!important}
[data-slot="sidebar"] [aria-label^="New thread"]:active{scale:.9}
[data-testid$="-shelf-toggle"]{border-radius:var(--sx-r-md)!important;font-size:11px!important;font-weight:600!important;letter-spacing:.07em!important;text-transform:uppercase;color:var(--sx-fg-3)!important}
[data-testid$="-shelf-toggle"]:hover{color:var(--sx-fg)!important;background:var(--sx-hover)!important}
[data-testid$="-shelf-toggle"] .tabular-nums{letter-spacing:0;font-size:11px;padding:0 6px;border-radius:999px;background:var(--sx-hover)}
[data-testid="sidebar-working-shelf-toggle"]{color:var(--sx-accent-ink)!important}
[data-testid="sidebar-working-shelf-toggle"]::after{content:"";order:-1;flex:none;width:6px;height:6px;margin-right:2px;border-radius:50%;background:var(--sx-accent);box-shadow:0 0 8px var(--sx-accent);animation:sx-dot 2.4s var(--sx-inout) infinite}
/* a working thread shows its live timer, not the word "Working" (FRAGILE: the timer is the status's aria-hidden child) */
